"""reply — 统一返回（每个意图都有 message；一句一个「总返回」；异步也可等）

用户需求：
  ① 每个意图都要有 message 返回（成功或失败都算）—— 空的补一个，不许静默
  ② 这个返回是【总的返回】—— 一句里所有意图（含 A 路抢跑/听写）汇总成一条
  ③ 异步函数要等处理完成才能最终返回 —— wait_utterance() 能阻塞到最终结果

实现（严格加法，不改既有业务逻辑）：
  · install() 包住三处：
      - actions.dispatch / voice_agent.dispatch : 保证 msg 非空 + 每次调用记一笔
      - Agent._dictate_async / Agent._dictate  : 听写算"未完成的异步工作"(pending)
      - typein.type_text                       : 听写线程完成 → 补记 dictation 结果
  · begin(agent)  一句开始（voice_agent.handle 开头）→ 重置本句账本
  · flush(agent)  本句结束 → 打一行 `⇒ 总返回：…` + 存 agent.last_reply
  · wait_utterance(agent, timeout) → 阻塞到"本句真的处理完（含异步补记）"再返回

为什么用"空闲定时器"而不是在每个 return 前插 flush：handle() 有 10+ 个 return
分支，逐个插入容易漏；"最后一次记账后 idle_s 无新账 → 收账"覆盖所有分支。
⚠️ 不会阻塞音频主循环：定时器与 pending 计数都是旁路；wait 只给外部调用方用。
"""
from __future__ import annotations

import threading
import time

try:
    from dlog import log
except Exception:                                     # 兜底
    def log(msg="", tag=None, **kw):
        print(msg, flush=True)

IDLE_S = 1.5          # 最后一次记账后多久算"这句完了"
PENDING_IDLE_S = 0.8  # 异步工作（听写）刚结束 → 稍等一下再收账

_LOCK = threading.RLock()
_AGENT = None          # 当前 agent（进程内通常只有一个；begin() 每次刷新）
_ST = {}               # id(agent) -> 账本
_ORIG = {}             # 原始函数（回滚用）
_INSTALLED = False


def set_agent(agent):
    global _AGENT
    _AGENT = agent


def _st(agent):
    if agent is None:
        return None
    k = id(agent)
    s = _ST.get(k)
    if s is None:
        s = {"items": [], "timer": None, "ev": threading.Event(),
             "t0": 0.0, "final": None, "pending": 0}
        _ST[k] = s
    return s


def begin(agent, idle_s=IDLE_S):
    """一句开始：清账本 + 起定时器（voice_agent.handle 开头调用）"""
    set_agent(agent)
    s = _st(agent)
    if s is None:
        return
    with _LOCK:
        s["items"] = []
        s["t0"] = time.time()
        s["final"] = None
        s["ev"].clear()
        _arm(agent, s, idle_s)


def _arm(agent, s, idle_s=IDLE_S):
    t = s.get("timer")
    if t is not None:
        try:
            t.cancel()
        except Exception:
            pass
    nt = threading.Timer(float(idle_s), flush, args=(agent,))
    nt.daemon = True
    s["timer"] = nt
    nt.start()


def pending_add(agent=None):
    """有异步工作开始（听写线程）→ 收账前必须等它完成"""
    agent = agent or _AGENT
    s = _st(agent)
    if s is None:
        return
    with _LOCK:
        s["pending"] = int(s.get("pending", 0)) + 1


def pending_done(agent=None):
    agent = agent or _AGENT
    s = _st(agent)
    if s is None:
        return
    with _LOCK:
        s["pending"] = max(0, int(s.get("pending", 0)) - 1)
        if s["pending"] == 0:
            _arm(agent, s, PENDING_IDLE_S)


def _short(a, n=24):
    if a is None:
        return ""
    a = str(a)
    return a if len(a) <= n else a[:n] + "…"


def note(agent, intent, ok, msg, src="B", arg=None):
    """记一笔（消息为空 → 按成功/失败补一句，保证"每个意图都有 message"）"""
    if agent is None:
        agent = _AGENT
    if agent is None:
        return
    s = _st(agent)
    if s is None:
        return
    m = str(msg or "").strip()
    if not m:
        m = f"{'已完成' if ok else '未执行'}（{intent} 没有返回消息）"
    with _LOCK:
        s["items"].append({"intent": intent, "arg": _short(arg),
                           "ok": bool(ok), "msg": m, "src": src, "t": time.time()})
        _arm(agent, s)


def note_dictation(agent, ok, msg, arg=None):
    """听写线程完成后的补记（异步 → 也算进本句的"总返回"）"""
    note(agent, "dictation", ok, msg, src="dictate", arg=arg)


def fmt(items):
    ok = sum(1 for i in items if i["ok"])
    bad = len(items) - ok
    head = f"总返回：{ok} 成功" + (f" / {bad} 失败" if bad else "")
    body = "；".join(f"{i['intent']}→{'✅' if i['ok'] else '❌'} {i['msg']}" for i in items)
    return f"{head} ｜ {body}" if body else head


def flush(agent=None):
    """本句收账 → 打「总返回」+ 存 agent.last_reply（返回 reply dict）"""
    agent = agent or _AGENT
    s = _st(agent)
    if s is None:
        return None
    with _LOCK:
        if int(s.get("pending", 0)) > 0:      # 还有异步在跑 → 等它完成再收账
            _arm(agent, s, PENDING_IDLE_S)
            return None
        items = list(s["items"])
        s["items"] = []
        s["timer"] = None
        if not items:
            return None
        rep = {"ok": all(i["ok"] for i in items),
               "executed": sum(1 for i in items if i["ok"]),
               "failed": sum(1 for i in items if not i["ok"]),
               "items": items, "text": fmt(items), "ts": time.time()}
        s["final"] = rep
        s["ev"].set()
    try:
        setattr(agent, "last_reply", rep)
    except Exception:
        pass
    # 单条就不打「总返回」了（那条意图自己的行已经是它的返回）；
    # 多条才打——这才是"汇总"的意义。agent.last_reply 永远都会有。
    if len(rep["items"]) >= 2:
        log(f"   ⇒ {rep['text']}", "ACT")
    return rep


def wait_utterance(agent=None, timeout=8.0):
    """阻塞等到"本句处理完（含听写等异步补记）"→ 返回总返回 dict；没内容返回 None。

    外部调用方（工具/MCP 桥）用法：
        agent.handle(wav)
        rep = reply.wait_utterance(agent)
        if rep: print(rep["ok"], rep["text"])
    """
    agent = agent or _AGENT
    s = _st(agent)
    if s is None:
        return None
    if s["final"] is None:
        s["ev"].wait(float(timeout))
    return s["final"]


# ══════════════════════════════════════════════════════════════
#  安装：包住 dispatch / 听写（保证 message + 自动记账 + 异步可见）
# ══════════════════════════════════════════════════════════════
def _wrap_dispatch(orig):
    def patched(*a, **kw):
        intent = a[0] if a else kw.get("intent")
        arg = a[1] if len(a) > 1 else kw.get("arg")
        cfg = a[2] if len(a) > 2 else kw.get("cfg")
        try:
            from . import micwatch as _mw
            _mw.mark(f"动作:{intent}")
        except Exception:
            _mw = None
        try:
            # ★ 唯一开关：intent_config.json 里 enabled=false 的意图，任何路径都不执行
            try:
                from . import intents as _intents
                if intent and intent != "unknown" and not _intents.enabled(cfg, intent):
                    msg = (f"意图 {intent} 已关闭（intent_config.json 的 intent_registry "
                           f"里 enabled=false，域 {_intents.tag_of(cfg, intent)}）")
                    note(_AGENT, intent, False, msg, arg=arg)
                    return False, msg, None
            except Exception:
                pass
            ok, msg, info = orig(*a, **kw)
            m = str(msg or "").strip()
            if not m:
                m = f"{'已完成' if ok else '未执行'}（{intent} 没有返回消息）"
            note(_AGENT, intent, ok, m, arg=arg)
            return ok, m, info
        finally:
            if _mw is not None:
                try:
                    _mw.mark(f"动作:{intent}", False)
                except Exception:
                    pass
    patched.__name__ = getattr(orig, "__name__", "dispatch")
    patched.__oc_wrapped__ = True
    return patched


def _wrap_typein(orig):
    def patched(s, dry=False, *a, **kw):
        ok, msg = orig(s, dry=dry, *a, **kw)
        note_dictation(_AGENT, ok, msg, arg=(str(s)[:24] if s else None))
        return ok, msg
    patched.__name__ = getattr(orig, "__name__", "type_text")
    patched.__oc_wrapped__ = True
    return patched


def _wrap_dictate_async(orig):
    def patched(self, *a, **kw):
        pending_add(self)                    # 听写是异步的 → 收账前等它
        try:
            return orig(self, *a, **kw)
        except Exception:
            pending_done(self)               # 没能起线程 → 别把账本挂死
            raise
    patched.__name__ = getattr(orig, "__name__", "_dictate_async")
    patched.__oc_wrapped__ = True
    return patched


def _wrap_dictate(orig):
    def patched(self, *a, **kw):
        try:
            from . import micwatch as _mw
            _mw.mark("听写")
        except Exception:
            _mw = None
        try:
            return orig(self, *a, **kw)
        finally:
            if _mw is not None:
                try:
                    _mw.mark("听写", False)
                except Exception:
                    pass
            pending_done(self)               # 线程里跑完 → 放行收账
    patched.__name__ = getattr(orig, "__name__", "_dictate")
    patched.__oc_wrapped__ = True
    return patched


def install():
    """包住 dispatch / 听写 / type_text（幂等）"""
    global _INSTALLED
    if _INSTALLED:
        return True
    import actions as _act
    if not getattr(_act.dispatch, "__oc_wrapped__", False):
        _ORIG["actions.dispatch"] = _act.dispatch
        _act.dispatch = _wrap_dispatch(_act.dispatch)
    try:
        import voice_agent as _va
        if not getattr(_va.dispatch, "__oc_wrapped__", False):
            _ORIG["voice_agent.dispatch"] = _va.dispatch
            _va.dispatch = _wrap_dispatch(_va.dispatch)
        if not getattr(_va.Agent._dictate_async, "__oc_wrapped__", False):
            _ORIG["Agent._dictate_async"] = _va.Agent._dictate_async
            _va.Agent._dictate_async = _wrap_dictate_async(_va.Agent._dictate_async)
        if not getattr(_va.Agent._dictate, "__oc_wrapped__", False):
            _ORIG["Agent._dictate"] = _va.Agent._dictate
            _va.Agent._dictate = _wrap_dictate(_va.Agent._dictate)
    except Exception:
        pass
    try:
        import typein as _ti
        if not getattr(_ti.type_text, "__oc_wrapped__", False):
            _ORIG["typein.type_text"] = _ti.type_text
            _ti.type_text = _wrap_typein(_ti.type_text)
    except Exception:
        pass
    _INSTALLED = True
    return True


